<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$activeNav='community';$uid=current_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_login();verify_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='photo'){$lid=(int)($_POST['listing_id']??0);$s=db()->prepare("SELECT id FROM listings WHERE id=:l AND status='published'");$s->execute([':l'=>$lid]);if(!$s->fetchColumn())throw new RuntimeException('Choose a published business.');$path=upload_listing_image($_FILES['photo']??[]);if(!$path)throw new RuntimeException('Choose a photo to upload.');$caption=text_substr(trim((string)($_POST['caption']??'')),0,180);db()->prepare("INSERT INTO listing_photos(listing_id,user_id,image_path,caption,status) VALUES(:l,:u,:p,:c,'pending')")->execute([':l'=>$lid,':u'=>$uid,':p'=>$path,':c'=>$caption]);flash('success','Photo submitted for moderator review.');}
  elseif($action==='guide'){$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$city=trim((string)($_POST['city']??''));$items=array_slice(array_values(array_unique(array_filter(array_map('intval',$_POST['listing_ids']??[])))),0,12);if($title===''||text_len($title)>100||text_len($desc)<30||!$items)throw new RuntimeException('Add a title, a description of at least 30 characters and at least one place.');$slug=slugify($title).'-'.bin2hex(random_bytes(3));$p=db();$p->beginTransaction();$p->prepare("INSERT INTO guides(user_id,title,slug,description,city,status) VALUES(:u,:t,:s,:d,:c,'pending')")->execute([':u'=>$uid,':t'=>$title,':s'=>$slug,':d'=>text_substr($desc,0,1500),':c'=>text_substr($city,0,100)]);$gid=(int)$p->lastInsertId();$st=$p->prepare("INSERT OR IGNORE INTO guide_items(guide_id,listing_id,position) SELECT :g,id,:pos FROM listings WHERE id=:l AND status='published'");foreach($items as $i=>$lid)$st->execute([':g'=>$gid,':pos'=>$i,':l'=>$lid]);if((int)$p->query('SELECT COUNT(*) FROM guide_items WHERE guide_id='.$gid)->fetchColumn()===0)throw new RuntimeException('No valid published places were selected.');$p->commit();flash('success','Your city guide has been submitted for approval.');}
  elseif($action==='question'){$lid=(int)($_POST['listing_id']??0);$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$s=db()->prepare("SELECT id FROM listings WHERE id=:l AND status='published'");$s->execute([':l'=>$lid]);if(!$s->fetchColumn()||$title===''||text_len($title)>140||text_len($body)<10)throw new RuntimeException('Choose a place and write a clear question.');db()->prepare("INSERT INTO questions(listing_id,user_id,title,body,status) VALUES(:l,:u,:t,:b,'pending')")->execute([':l'=>$lid,':u'=>$uid,':t'=>$title,':b'=>text_substr($body,0,1500)]);flash('success','Question submitted for review.');}
  elseif($action==='answer'){$qid=(int)($_POST['question_id']??0);$body=trim((string)($_POST['body']??''));$s=db()->prepare("SELECT q.id,l.owner_user_id FROM questions q JOIN listings l ON l.id=q.listing_id WHERE q.id=:q AND q.status='published'");$s->execute([':q'=>$qid]);$q=$s->fetch();if(!$q||text_len($body)<5||text_len($body)>1500)throw new RuntimeException('Write an answer of at least 5 characters.');db()->prepare("INSERT INTO answers(question_id,user_id,body,is_owner_answer,status) VALUES(:q,:u,:b,:o,'pending')")->execute([':q'=>$qid,':u'=>$uid,':b'=>$body,':o'=>(int)$q['owner_user_id']===$uid?1:0]);flash('success','Answer submitted for moderation.');}
  elseif($action==='recommendation'){$lid=(int)($_POST['listing_id']??0);$note=trim((string)($_POST['note']??''));$s=db()->prepare("SELECT id FROM listings WHERE id=:l AND status='published'");$s->execute([':l'=>$lid]);if(!$s->fetchColumn()||text_len($note)<15)throw new RuntimeException('Choose a published place and add a recommendation note.');db()->prepare("INSERT INTO recommendations(listing_id,user_id,note,status) VALUES(:l,:u,:n,'pending')")->execute([':l'=>$lid,':u'=>$uid,':n'=>text_substr($note,0,700)]);flash('success','Your recommendation is awaiting community review.');}
  elseif($action==='follow'){$target=(int)($_POST['contributor_id']??0);if($target===$uid)throw new RuntimeException('You cannot follow yourself.');$s=db()->prepare("SELECT id FROM users WHERE id=:id AND is_active=1 AND profile_visibility='public'");$s->execute([':id'=>$target]);if(!$s->fetchColumn())throw new RuntimeException('Contributor not found.');$s=db()->prepare('SELECT 1 FROM contributor_follows WHERE follower_id=:u AND contributor_id=:t');$s->execute([':u'=>$uid,':t'=>$target]);if($s->fetchColumn())db()->prepare('DELETE FROM contributor_follows WHERE follower_id=:u AND contributor_id=:t')->execute([':u'=>$uid,':t'=>$target]);else db()->prepare('INSERT OR IGNORE INTO contributor_follows(follower_id,contributor_id) VALUES(:u,:t)')->execute([':u'=>$uid,':t'=>$target]);flash('success','Contributor follow preference updated.');}
  elseif($action==='report'){$type=(string)($_POST['content_type']??'listing');$cid=(int)($_POST['content_id']??0);$reason=(string)($_POST['reason']??'');$details=trim((string)($_POST['details']??''));if(!in_array($type,['listing','review','photo','guide','question','answer','event','offer'],true)||$cid<1||!in_array($reason,['incorrect','duplicate','spam','inappropriate','closed','other'],true))throw new RuntimeException('Choose a valid report reason.');db()->prepare("INSERT INTO content_reports(reporter_id,content_type,content_id,reason,details) VALUES(:u,:t,:i,:r,:d)")->execute([':u'=>$uid,':t'=>$type,':i'=>$cid,':r'=>$reason,':d'=>text_substr($details,0,700)]);flash('success','Thank you. Your report was sent to the moderation team.');}
  elseif($action==='helpful'){$rid=(int)($_POST['review_id']??0);$s=db()->prepare("SELECT id FROM reviews WHERE id=:id AND status='approved'");$s->execute([':id'=>$rid]);if(!$s->fetchColumn())throw new RuntimeException('Review not found.');db()->prepare('INSERT INTO review_votes(review_id,user_id,helpful) VALUES(:r,:u,1) ON CONFLICT(review_id,user_id) DO UPDATE SET helpful=1')->execute([':r'=>$rid,':u'=>$uid]);flash('success','Thanks for marking this review helpful.');}
  elseif($action==='recommend_vote'){$rid=(int)($_POST['recommendation_id']??0);$s=db()->prepare("SELECT id FROM recommendations WHERE id=:id AND status='published'");$s->execute([':id'=>$rid]);if(!$s->fetchColumn())throw new RuntimeException('Recommendation not found.');db()->prepare('INSERT OR IGNORE INTO recommendation_votes(recommendation_id,user_id) VALUES(:r,:u)')->execute([':r'=>$rid,':u'=>$uid]);flash('success','Your community vote was recorded.');}
  else throw new RuntimeException('Unknown community action.');
 }catch(Throwable $e){if(isset($p)&&$p instanceof PDO&&$p->inTransaction())$p->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'Unable to submit your contribution. Please try again.');}
 $to=(string)($_POST['return_to']??'community.php');redirect(local_return_url($to,'community.php'));
}
$guides=db()->query("SELECT g.*,u.name creator,(SELECT COUNT(*) FROM guide_items gi WHERE gi.guide_id=g.id) place_count FROM guides g JOIN users u ON u.id=g.user_id WHERE g.status='published' ORDER BY g.created_at DESC LIMIT 12")->fetchAll();
$photos=db()->query("SELECT p.*,l.name listing_name,u.name contributor FROM listing_photos p JOIN listings l ON l.id=p.listing_id LEFT JOIN users u ON u.id=p.user_id WHERE p.status='approved' ORDER BY p.created_at DESC LIMIT 16")->fetchAll();
$questions=db()->query("SELECT q.*,l.name listing_name,l.slug,u.name asker,(SELECT COUNT(*) FROM answers a WHERE a.question_id=q.id AND a.status='published') answer_count FROM questions q JOIN listings l ON l.id=q.listing_id JOIN users u ON u.id=q.user_id WHERE q.status='published' ORDER BY q.created_at DESC LIMIT 12")->fetchAll();
$recs=db()->query("SELECT r.*,l.name listing_name,l.slug,u.name contributor,(SELECT COUNT(*) FROM recommendation_votes v WHERE v.recommendation_id=r.id) votes FROM recommendations r JOIN listings l ON l.id=r.listing_id JOIN users u ON u.id=r.user_id WHERE r.status='published' ORDER BY votes DESC,r.created_at DESC LIMIT 12")->fetchAll();
$contributors=db()->query("SELECT u.id,u.name,u.bio,(SELECT COUNT(*) FROM reviews r WHERE r.user_id=u.id AND r.status='approved') reviews_count,(SELECT COUNT(*) FROM guides g WHERE g.user_id=u.id AND g.status='published') guides_count,(SELECT COUNT(*) FROM listing_photos p WHERE p.user_id=u.id AND p.status='approved') photos_count,(SELECT COUNT(*) FROM contributor_follows f WHERE f.contributor_id=u.id) followers FROM users u WHERE u.is_active=1 AND u.role<>'admin' AND u.profile_visibility='public' ORDER BY (reviews_count+guides_count+photos_count) DESC,u.created_at ASC LIMIT 8")->fetchAll();
$publishedListings=db()->query("SELECT id,name,city,location FROM listings WHERE status='published' ORDER BY name LIMIT 200")->fetchAll();$pageTitle='Local community | '.setting('site_name','MetroGuide');$pageDescription='Share local guides, photos, recommendations and helpful answers.';include __DIR__.'/includes/header.php';
?>
