<section class="account-section" id="guides"><div class="section-heading"><div><span class="eyebrow">LOCAL EDITORIALS</span><h2>Community city guides</h2></div></div><?php if($guides): ?><div class="lg3-feature-grid"><?php foreach($guides as $g): ?><a href="<?= app_path('guide.php?slug='.rawurlencode($g['slug'])) ?>"><i class="fa-solid fa-map-marked-alt"></i><strong><?= h($g['title']) ?></strong><span><?= h($g['city']) ?> · <?= (int)$g['place_count'] ?> places · by <?= h($g['creator']) ?></span><p><?= h(text_excerpt($g['description'],130)) ?></p></a><?php endforeach; ?></div><?php else: ?><p class="muted">No published guides yet. Community submissions are reviewed before publication.</p><?php endif; ?></section>
<section class="account-section" id="photos"><div class="section-heading"><div><span class="eyebrow">REAL LOCAL MOMENTS</span><h2>Community photos</h2></div></div><?php if($photos): ?><div class="lg3-photo-grid"><?php foreach($photos as $p): ?><figure><img src="<?= app_path($p['image_path']) ?>" alt="<?= h($p['caption']?:$p['listing_name']) ?>" loading="lazy"><figcaption><strong><?= h($p['listing_name']) ?></strong><small><?= h($p['caption']) ?> · <?= h($p['contributor']??'Community') ?></small></figcaption></figure><?php endforeach; ?></div><?php else: ?><p class="muted">No approved community photos yet.</p><?php endif; ?></section>
<section class="account-section" id="contributors"><div class="section-heading"><div><span class="eyebrow">KNOWLEDGE KEEPERS & LEADERBOARD</span><h2>Top local contributors</h2><p>Points earned by contributing reviews (+10), city guides (+30), photos (+15), and helpful votes.</p></div></div><div class="lg3-contributor-grid"><?php $rank=1; foreach($contributors as $c): $score=((int)$c['reviews_count']*10)+((int)$c['guides_count']*30)+((int)$c['photos_count']*15)+((int)$c['followers']*5); $badge=$score>=150?'🌟 City Ambassador':($score>=60?'🧭 Master Guide':($score>=20?'🎒 Local Scout':'📍 Explorer')); $medal=$rank===1?'🥇':($rank===2?'🥈':($rank===3?'🥉':'#'.$rank)); ?><article class="content-panel" style="position:relative;"><div style="position:absolute;top:12px;right:14px;font-size:1.15rem;font-weight:700;"><?= $medal ?></div><div class="lg3-contributor-avatar"><?= h(text_upper(text_substr($c['name'],0,1))) ?></div><h3><a href="<?= app_path('contributor.php?id='.(int)$c['id']) ?>"><?= h($c['name']) ?></a></h3><span class="status-pill status-approved"><?= h($badge) ?></span><div style="font-weight:700;color:#146b60;margin:6px 0 2px 0;font-size:0.95rem;"><i class="fa-solid fa-award"></i> <?= $score ?> points</div><p><?= h(text_excerpt($c['bio']?:'Sharing useful local knowledge.',110)) ?></p><small><?= (int)$c['reviews_count'] ?> reviews · <?= (int)$c['guides_count'] ?> guides · <?= (int)$c['photos_count'] ?> photos</small><?php if(current_user()&&(int)$c['id']!==$uid): ?><form method="post" action="community.php#contributors" style="margin-top:8px;"><?= csrf_field() ?><input type="hidden" name="action" value="follow"><input type="hidden" name="contributor_id" value="<?= (int)$c['id'] ?>"><button class="button button-outline button-small">Follow / unfollow</button></form><?php endif; ?></article><?php $rank++; endforeach; ?></div></section>
<section class="account-section" id="questions"><div class="section-heading"><div><span class="eyebrow">ASK & ANSWER</span><h2>Community Q&A</h2></div></div><?php foreach($questions as $q): ?><article class="lg3-question content-panel"><span class="eyebrow"><?= h($q['listing_name']) ?></span><h3><?= h($q['title']) ?></h3><p><?= nl2br(h($q['body'])) ?></p><small>Asked by <?= h($q['asker']) ?> · <?= (int)$q['answer_count'] ?> approved answers</small><?php $ans=db()->prepare("SELECT a.*,u.name FROM answers a JOIN users u ON u.id=a.user_id WHERE a.question_id=:q AND a.status='published' ORDER BY a.is_owner_answer DESC,a.created_at");$ans->execute([':q'=>$q['id']]);foreach($ans->fetchAll() as $a): ?><blockquote><strong><?= h($a['name']) ?> <?= (int)$a['is_owner_answer']?'· Business owner':'' ?></strong><p><?= nl2br(h($a['body'])) ?></p></blockquote><?php endforeach; ?><?php if(current_user()): ?><form method="post" class="lg3-inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="answer"><input type="hidden" name="question_id" value="<?= (int)$q['id'] ?>"><input type="hidden" name="return_to" value="community.php#questions"><input name="body" minlength="5" maxlength="1500" required placeholder="Share a helpful answer"><button class="button button-outline button-small">Answer</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$questions): ?><p class="muted">No public questions yet.</p><?php endif; ?></section>
<section class="account-section" id="recommendations"><div class="section-heading"><div><span class="eyebrow">COMMUNITY SHORTLIST</span><h2>Recommended by locals</h2></div></div><div class="lg3-feature-grid"><?php foreach($recs as $r): ?><article><i class="fa-solid fa-thumbs-up"></i><strong><a href="<?= app_path('index.php?listing='.rawurlencode($r['slug'])) ?>"><?= h($r['listing_name']) ?></a></strong><p><?= h($r['note']) ?></p><small>Recommended by <?= h($r['contributor']) ?> · <?= (int)$r['votes'] ?> helpful votes</small><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="recommend_vote"><input type="hidden" name="recommendation_id" value="<?= (int)$r['id'] ?>"><button class="table-action">Helpful</button></form><?php endif; ?></article><?php endforeach; ?></div><?php if(!$recs): ?><p class="muted">No approved recommendations yet.</p><?php endif; ?></section>
